"""
Debug script to compare two embeddings
"""

import argparse
from typing import List
from sklearn.metrics.pairwise import cosine_similarity
import numpy as np


def compare_embeddings(embedding1: List[float], embedding2: List[float]) -> float:
    """Compare two embeddings using cosine similarity.

    Args:
        embedding1 (List[float]): First embedding vector.
        embedding2 (List[float]): Second embedding vector.

    Returns:
        float: Cosine similarity score between the two embeddings.
    """

    emb1 = np.array(embedding1).reshape(1, -1)
    emb2 = np.array(embedding2).reshape(1, -1)

    similarity = cosine_similarity(emb1, emb2)[0][0]
    return similarity


